public static function replaceFirst(string $target, string $replacement, string $subject)
    {
        $pos = strpos($subject, $target);

        /* No operations needed if target does not exist */
        if($pos === false) return $subject;

        $str = '';

        for($n = 0; $n < strlen($subject); $n++) {
            if($n < $pos || $n > $pos + strlen($target) -1) {
                $str .= substr($subject, $n, 1);
            }
            else {
                $str .= substr($replacement, $n - $pos, 1);
            }
        }

        return $str;
    }

def translate(source, dictionary):
    '''A dictionary with a one-to-one translation of keywords is used
    to provide the transformation.
    '''
    toks = tokenize.generate_tokens(StringIO(source).readline)
    result = []
    for toktype, tokvalue, _, _, _ in toks:
        if toktype == tokenize.NAME and tokvalue in dictionary:
            result.append((toktype, dictionary[tokvalue]))
        else:
            result.append((toktype, tokvalue))
    return tokenize.untokenize(result)

