public static double KullbackLeiblerDivergence(double[] p, double[] q) {
        boolean intersection = false;
        double k = 0;

        for (int i = 0; i < p.length; i++) {
            if (p[i] != 0 && q[i] != 0) {
                intersection = true;
                k += p[i] * Math.log(p[i] / q[i]);
            }
        }

        if (intersection)
            return k;
        else
            return Double.POSITIVE_INFINITY;
    }

public static function log( $message, $level = Logger::INFO, $context = array() )
    {
        static $_firstRun = true;

        if ( $_firstRun || !static::$_logFileValid )
        {
            static::_checkLogFile();
            $_firstRun = false;
        }

        //	Get the indent, if any
        $_unindent = ( ( $_newIndent = static::_processMessage( $message ) ) > 0 );

        //	Indent...
        if ( 0 > ( $_tempIndent = static::$_currentIndent - ( $_unindent ? 1 : 0 ) ) )
        {
            $_tempIndent = 0;
        }

        $_message = str_repeat( '  ', $_tempIndent ) . $message;

        if ( !is_numeric( $level ) )
        {
            $level = LoggingLevels::toNumeric( $level );
        }

        if ( static::$_logger )
        {
            static::$_logger->addRecord( $level, $_message, !is_array( $context ) ? array() : $context );
        }
        elseif ( static::$_fallbackLogger )
        {
            static::$_fallbackLogger->addRecord( $level, $_message, $context );
        }

        //	Set indent level...
        static::$_currentIndent += $_newIndent;

        //	Anything over a warning returns false so you can chain
        return ( Logger::WARNING > $level );
    }

async function nextVersion (bumpType, version) {
  if (utils.isNightly(version) || utils.isBeta(version)) {
    switch (bumpType) {
      case 'nightly':
        version = await utils.nextNightly(version)
        break
      case 'beta':
        version = await utils.nextBeta(version)
        break
      case 'stable':
        version = semver.valid(semver.coerce(version))
        break
      default:
        throw new Error('Invalid bump type.')
    }
  } else if (utils.isStable(version)) {
    switch (bumpType) {
      case 'nightly':
        version = utils.nextNightly(version)
        break
      case 'beta':
        throw new Error('Cannot bump to beta from stable.')
      case 'stable':
        version = semver.inc(version, 'patch')
        break
      default:
        throw new Error('Invalid bump type.')
    }
  } else {
    throw new Error(`Invalid current version: ${version}`)
  }
  return version
}

